  AvgCommunicate_134101_Content_11 = {
    Text = "多虧您的恩賜，我已能徹底看清您的靈魂，知曉世界本來的面貌。"
  },
  AvgCommunicate_134101_Content_12 = {
    Text = "光明，光明……原來世界本是黑暗與混沌，是有神明選擇了犧牲，太陽才變作了真實，眾生才得以維持存在的幸福……"
  },
  AvgCommunicate_134101_Content_13 = {
    Text = "你是不是讀經文讀得太多了，感覺你需要稍微冷靜一下。"
  },
  AvgCommunicate_134101_Content_14 = {
    Text = "我明白，您希望融入眾生之中，不願端坐於神座之上。"
  },
  AvgCommunicate_134101_Content_15 = {
    Text = "您的無私，您的奉獻，您的犧牲……"
  },
  AvgCommunicate_134101_Content_16 = {
    Text = "從今往後我會以最忠誠的……不，以永遠的朋友的身份與您交往。"
  },
  AvgCommunicate_134101_Content_17 = {
    Text = "願這顆永不熄滅的聖心，能為您驅散所有黑暗。"
  },
  AvgCommunicate_134101_Content_2 = {
    Text = "您……您何止是太陽，您原來是宇宙的中心，是世界誕生的起點。"
  },
  AvgCommunicate_134101_Content_3 = {
    Text = "我們都這麼熟了，你怎麼比以前更加畢恭畢敬了？"
  },
  AvgCommunicate_134101_Content_4 = {
    Text = "因為我明白了，眾生未曾尊崇匍匐於您的腳下，只因他們生來愚鈍而盲目，無法得見您的本質！"
  },
  AvgCommunicate_134101_Content_5 = {
    Text = "螻蟻如何見識巨象的全貌？曾經我也只能依靠聖心，短淺地窺視到您力量的冰山一角。"
  },
  AvgCommunicate_134101_Content_6 = {
    Text = "即便這樣，聖心也會因此感到針刺般的疼痛，只要再向您的靈魂多看一眼，我便可能會崩潰而亡。"
