    Text = "感謝你把這麼貴重的東西交給我，%player%。"
  },
  AvgCommunicate_134202_Content_10 = {
    Text = "我覺得這可能是在告訴我，除了在記憶中留下影子，世界也可以透過腳步去丈量。"
  },
  AvgCommunicate_134202_Content_11 = {
    Text = "無法留住，就一直、一直向前，世界和你們都會替我記住的。"
  },
  AvgCommunicate_134202_Content_12 = {
    Text = "連我都忍不住熱血起來了……"
  },
  AvgCommunicate_134202_Content_13 = {
    Text = "我會成為最偉大的探險家，最厲害的機械大師，%player%，我想正式向你發出邀請。"
  },
  AvgCommunicate_134202_Content_14 = {
    Text = "等到一切都解決了的那一天，請和我一起去探險吧，在這個世界裡創造更多珍貴的記憶。"
  },
  AvgCommunicate_134202_Content_15 = {
    Text = "或許這一天很遠，也或許就在明天。"
