  },
  AvgCommunicate_134202_Content_6 = {
    Text = "為什麼是這麼驕傲的語氣啊！"
  },
  AvgCommunicate_134202_Content_7 = {
    Text = "因為，雖然可能還是會忘掉很多事情，但過去和現在，%player%都會一直提醒我，幫我記住。"
  },
  AvgCommunicate_134202_Content_8 = {
    Text = "我是誰，我在哪，我要做什麼，會由我最信任的人們告訴我。"
  },
  AvgCommunicate_134202_Content_9 = {
    Text = "也許就是因為這樣，在領悟最終法則以後，雖然記憶力沒有變好，但我感覺整個世界像一幅廣闊的地圖，在我眼前展開。"
  },
  AvgCommunicate_134202_Option_3 = {
    Text = "你的記憶力變好了？"
  },
  AvgCommunicate_134208_Content_1 = {
    Text = "我曾以為，只有通過扮演觀眾的方式，才能體會到未知的樂趣。"
  },
  AvgCommunicate_134208_Content_10 = {
    Text = "雖然沒有完全理解……不過聽上去應該是件好事？"
  },
  AvgCommunicate_134208_Content_11 = {
    Text = "自我從那扇門扉離開之後，這是我所遇見的最大的幸事。"
  },
  AvgCommunicate_134208_Content_12 = {
    Text = "守密人，這是您所給予我的，我所無法預見的驚喜。"
  },
  AvgCommunicate_134208_Content_13 = {
    Text = "命運從不辜負慷慨的饋贈者。"
  },
  AvgCommunicate_134208_Content_14 = {
    Text = "我無法觸碰您的絲線，但在您為命運而戰之時，我的紡輪將永遠為您轉動。"
  },
  AvgCommunicate_134208_Content_2 = {
    Text = "我已經很久、很久，沒有體驗過這種感覺了……"
