  },
  AvgCommunicate_134245_Content_8 = {
    Text = "唔，讓沙耶想想……"
  },
  AvgCommunicate_134245_Option_2 = {Text = "沒問題"},
  AvgCommunicate_134246_Content_1 = {
    Text = "卡拉布親愛的、最愛的、了不起的貴人～"
