  },
  AvgCommunicate_134263_Content_22 = {
    Text = "你過來就知道了。"
  },
  AvgCommunicate_134263_Content_23 = {
    Text = "好吧……那你等我一會。現在外面在下雨，我得先回宿舍拿傘。"
  },
  AvgCommunicate_134263_Content_24 = {
    Text = "別磨蹭了，我們接下來的計劃用不到傘。"
