  AvgCommunicate_149987_Content_7 = {
    Text = "是的，我也一直很在意這無形之物的本質，或許足夠了解後才能更好地控制祂。"
  },
  AvgCommunicate_149987_Content_8 = {
    Text = "雖說來到彌薩格後我才發現，難以理解的存在遠比我想像的還多......"
  },
  AvgCommunicate_149987_Content_9 = {
    Text = "所以我決定先更多地學習腐蝕相關的知識，畢竟這也是主君長期以來對抗的敵人。"
  },
  AvgCommunicate_149988_Content_1 = {
    Text = "我那不聽話，總是滿世界亂跑的小狗啊。"
