  AvgCommunicate_72037_Content_3 = {
    Text = "？！你怎麼知道的？"
  },
  AvgCommunicate_72037_Content_4 = {
    Text = "余在夢境中度過的時間遠比在常世中要多，你是在質疑一個活在夢境中的人的感知嗎？"
  },
  AvgCommunicate_72037_Content_5 = {
    Text = "除了預言，余有時也會做一些與常人一樣的夢，但那些都不會像昨日的夢一樣如此真實、如此連續……"
